command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
Set-Location -LiteralPath $repo
& git fetch origin work/test-infra-simplify-20261005 --no-tags --prune
if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
$temp=Join-Path $env:RUNNER_TEMP ("test-infra-simplify-final-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp f5b3fc72894f2545063a634283c6c714414a2ecf
  if($LASTEXITCODE -ne 0){throw "candidate worktree failed"}
  Set-Location -LiteralPath $temp
  & python -X utf8 tools\winui\run_checks.py fast --before 974926d9d3a0ef1015477a9a7ff2409486e988be --head f5b3fc72894f2545063a634283c6c714414a2ecf
  if($LASTEXITCODE -ne 0){throw "final change-scoped FAST validation failed"}
  Write-Host "TEST_INFRA_SIMPLIFY_FINAL_FAST=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
